{
  "core_question": "How should a US-based clinical-stage biotech structure and value a co-development/co-commercialization agreement with an EU-based pharma for a Phase 3 oncology asset, balancing clinical, regulatory, IP, legal, and financial risks?",
  "rationale": "The deal involves clinical‑program risk assessment (healthcare), jurisdictional rights and regulatory/IP exposure across US/EU/UK (legal), and valuation metrics such as rNPV, milestone calibration, and royalty structuring (finance).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "Given a single Phase 3 oncology asset with potential FDA accelerated‑approval eligibility, what are the key clinical‑program risks that should be quantified for valuation purposes, and how can milestone payments be calibrated to reflect realistic probability of regulatory success and market launch?",
    "legal": "What contractual provisions and IP protection strategies are essential when structuring a territorial split (US rights to the biotech, EU/UK rights to the pharma) in a co‑development/co‑commercialization deal, particularly regarding FDA approval, EMA/British Medicines Agency approvals, and cross‑jurisdictional enforcement of patents?",
    "finance": "How should the biotech calculate an rNPV for this asset, incorporating upfront payments, milestone milestones, tiered royalty rates, and risk‑adjusted discount rates, and what sensitivity analyses would best illustrate the impact of regulatory approval uncertainty on deal economics?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "FDA accelerated‑approval guidance updates, EU/UK regulatory changes post‑Brexit, recent IP enforcement trends"
}
